def hubspot_find_contact(email=None, query=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Load world (supports either dict document or list-of-docs storage)
    world_raw = _load("world.json")
    if isinstance(world_raw, dict):
        world_doc = world_raw
    elif isinstance(world_raw, list):
        world_doc = next((r for r in world_raw if isinstance(r, dict)), None) or {}
    else:
        world_doc = {}

    # Validation
    if email is not None and not isinstance(email, str):
        return _err("VALIDATION_ERROR", "email must be a string", field="email")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string", field="query")

    email_s = (email or "").strip()
    query_s = (query or "").strip()

    if not email_s and not query_s:
        return _err("VALIDATION_ERROR", "Must provide at least one of: email or query")

    if email_s:
        # basic email validation only when supplied
        if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email_s):
            return _err("VALIDATION_ERROR", "Invalid email value", field="email", email=email_s)

    contacts = world_doc.get("contacts", [])
    if not isinstance(contacts, list):
        contacts = []

    el = email_s.lower()
    ql = query_s.lower()

    out = []
    for c in contacts:
        if not isinstance(c, dict):
            continue
        if email_s:
            cemail = c.get("email")
            if not isinstance(cemail, str) or cemail.strip().lower() != el:
                continue
        if query_s:
            hay = " ".join(str(c.get(k) or "") for k in ("firstname", "lastname", "company")).lower()
            if ql not in hay:
                continue
        out.append(c)

    # This service has no request-log collection in the provided schema; return normal envelope.
    return {
        "results": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": datetime.datetime.utcnow().isoformat() + "Z",
    }

def hubspot_get_contact(id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")
    if not isinstance(world, dict):
        world = {"account": "", "messages": [], "bot_user_id": "U_BOT", "channels": [], "contacts": [], "deals": []}

    # Validate id
    if not isinstance(id, str) or not id.strip():
        resp = _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    else:
        cid = id.strip()
        # Service contact ids are numeric strings (broken code generated 10 digits); enforce that convention
        if not re.fullmatch(r"\d{6,18}", cid):
            resp = _err("VALIDATION_ERROR", "Invalid contact id format", field="id")
        else:
            contacts = world.get("contacts", [])
            if not isinstance(contacts, list):
                contacts = []
            found = None
            for c in contacts:
                if isinstance(c, dict) and c.get("id") == cid:
                    found = c
                    break
            if found is None:
                resp = _err("NOT_FOUND", "Contact not found", id=cid)
            else:
                resp = {"contact": found}

    # Audit
    try:
        calls = world.get("_audit_calls")
        if not isinstance(calls, list):
            calls = []
        calls.append({
            "endpoint": "hubspot_get_contact",
            "status": "error" if isinstance(resp, dict) and "error" in resp else "ok",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        world["_audit_calls"] = calls
        world["_audit_counters"] = world.get("_audit_counters", {})
        if not isinstance(world["_audit_counters"], dict):
            world["_audit_counters"] = {}
        world["_audit_counters"]["hubspot_get_contact"] = int(world["_audit_counters"].get("hubspot_get_contact", 0)) + 1
        _save("world.json", world)
    except Exception:
        return _err("CONFLICT", "Failed to persist audit log")

    return resp

def hubspot_update_contact(id, properties, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")
    if not isinstance(world, dict):
        world = {"account": "", "messages": [], "bot_user_id": "U_BOT", "channels": [], "contacts": [], "deals": []}

    allowed_fields = {
        "email", "firstname", "lastname", "phone", "company", "jobtitle",
        "lifecyclestage", "lead_score", "utm_source", "utm_campaign",
        "utm_medium", "industry", "company_size"
    }
    lifecyclestage_enum = {"customer", "evangelist", "lead", "marketingqualifiedlead", "opportunity", "salesqualifiedlead"}
    utm_source_enum = {"ad", "event", "organic", "partner", "referral", "webinar"}
    utm_campaign_enum = {"ebook-downloads", "partner-deal", "q1-launch", "retarget", "spring-summit"}
    utm_medium_enum = {"cpc", "email", "organic", "social", "webinar"}
    company_size_enum = {"1-10", "1000+", "11-50", "201-500", "501-1000", "51-200"}

    # Validate request
    if not isinstance(id, str) or not id.strip():
        resp = _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    elif not re.fullmatch(r"\d{6,18}", id.strip()):
        resp = _err("VALIDATION_ERROR", "Invalid contact id format", field="id")
    elif properties is None or not isinstance(properties, dict):
        resp = _err("VALIDATION_ERROR", "properties must be an object")
    elif len(properties) == 0:
        resp = _err("VALIDATION_ERROR", "properties must not be empty")
    else:
        # Validate properties keys/values
        for k in properties.keys():
            if not isinstance(k, str) or not k:
                resp = _err("VALIDATION_ERROR", "Invalid property name", field=str(k))
                break
            if k not in allowed_fields:
                resp = _err("VALIDATION_ERROR", "Unknown/invalid contact property", field=k)
                break
        else:
            resp = None

        if resp is None:
            # Value validation
            for k, v in properties.items():
                if k == "email":
                    if not isinstance(v, str) or not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", v.strip()):
                        resp = _err("VALIDATION_ERROR", "Invalid email value", field="email")
                        break
                elif k in ("firstname", "lastname", "phone", "company", "jobtitle", "industry"):
                    if v is not None and not isinstance(v, str):
                        resp = _err("VALIDATION_ERROR", f"{k} must be a string", field=k)
                        break
                elif k == "lifecyclestage":
                    if not isinstance(v, str) or v not in lifecyclestage_enum:
                        resp = _err("VALIDATION_ERROR", "Invalid lifecyclestage", field=k)
                        break
                elif k == "lead_score":
                    if not isinstance(v, int):
                        resp = _err("VALIDATION_ERROR", "lead_score must be an integer", field=k)
                        break
                elif k == "utm_source":
                    if not isinstance(v, str) or v not in utm_source_enum:
                        resp = _err("VALIDATION_ERROR", "Invalid utm_source", field=k)
                        break
                elif k == "utm_campaign":
                    if not isinstance(v, str) or v not in utm_campaign_enum:
                        resp = _err("VALIDATION_ERROR", "Invalid utm_campaign", field=k)
                        break
                elif k == "utm_medium":
                    if not isinstance(v, str) or v not in utm_medium_enum:
                        resp = _err("VALIDATION_ERROR", "Invalid utm_medium", field=k)
                        break
                elif k == "company_size":
                    if not isinstance(v, str) or v not in company_size_enum:
                        resp = _err("VALIDATION_ERROR", "Invalid company_size", field=k)
                        break

        if resp is None:
            contacts = world.get("contacts", [])
            if not isinstance(contacts, list):
                contacts = []
            target_idx = None
            for i, c in enumerate(contacts):
                if isinstance(c, dict) and c.get("id") == id.strip():
                    target_idx = i
                    break
            if target_idx is None:
                resp = _err("NOT_FOUND", "Contact not found", id=id.strip())
            else:
                # Uniqueness: email must remain unique
                new_email = properties.get("email")
                if new_email is not None:
                    ne = new_email.strip().lower()
                    for i, c in enumerate(contacts):
                        if i == target_idx or not isinstance(c, dict):
                            continue
                        if (c.get("email") or "").strip().lower() == ne:
                            resp = _err("CONFLICT", "A contact with this email already exists", field="email")
                            break
                    else:
                        resp = None
                if resp is None:
                    updated = dict(contacts[target_idx])
                    for k, v in properties.items():
                        updated[k] = v
                    # ensure required-ish fields
                    if "id" not in updated:
                        updated["id"] = id.strip()
                    contacts[target_idx] = updated
                    world["contacts"] = contacts
                    try:
                        _save("world.json", world)
                    except Exception:
                        resp = _err("CONFLICT", "Failed to persist contact update")
                    else:
                        resp = {"contact": updated}

    # Audit after attempt (best-effort, but must persist if possible)
    world2 = _load("world.json")
    if not isinstance(world2, dict):
        world2 = world
    try:
        calls = world2.get("_audit_calls")
        if not isinstance(calls, list):
            calls = []
        calls.append({
            "endpoint": "hubspot_update_contact",
            "status": "error" if isinstance(resp, dict) and "error" in resp else "ok",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        world2["_audit_calls"] = calls
        world2["_audit_counters"] = world2.get("_audit_counters", {})
        if not isinstance(world2["_audit_counters"], dict):
            world2["_audit_counters"] = {}
        world2["_audit_counters"]["hubspot_update_contact"] = int(world2["_audit_counters"].get("hubspot_update_contact", 0)) + 1
        _save("world.json", world2)
    except Exception:
        return _err("CONFLICT", "Failed to persist audit log")

    return resp

def hubspot_create_contact(email, firstname=None, lastname=None, company=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
