        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")
    if not isinstance(world, dict):
        world = {"account": "", "messages": [], "bot_user_id": "U_BOT", "channels": [], "contacts": [], "deals": []}

    # Validate inputs
    if not isinstance(email, str) or not email.strip():
        resp = _err("VALIDATION_ERROR", "email is required and must be a non-empty string", field="email")
    else:
        em = email.strip()
        if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", em):
            resp = _err("VALIDATION_ERROR", "Invalid email value", field="email")
        elif firstname is not None and not isinstance(firstname, str):
