        world2["_audit_calls"] = calls
        world2["_audit_counters"] = world2.get("_audit_counters", {})
        if not isinstance(world2["_audit_counters"], dict):
            world2["_audit_counters"] = {}
        world2["_audit_counters"]["hubspot_create_contact"] = int(world2["_audit_counters"].get("hubspot_create_contact", 0)) + 1
        _save("world.json", world2)
    except Exception:
        return _err("CONFLICT", "Failed to persist audit log")

    return resp

def gmail_find_email(from_contains=None, subject_contains=None, label=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Load world (supports either dict document or list-of-docs storage)
    world_raw = _load("world.json")
    if isinstance(world_raw, dict):
        world_doc = world_raw
    elif isinstance(world_raw, list):
        world_doc = next((r for r in world_raw if isinstance(r, dict)), None) or {}
    else:
        world_doc = {}

    # Validation
    if from_contains is not None and not isinstance(from_contains, str):
        return _err("VALIDATION_ERROR", "from_contains must be a string", field="from_contains")
    if subject_contains is not None and not isinstance(subject_contains, str):
        return _err("VALIDATION_ERROR", "subject_contains must be a string", field="subject_contains")
    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string", field="label")

    fc = (from_contains or "").strip()
    sc = (subject_contains or "").strip()
    lab = (label or "").strip()

    if not fc and not sc and not lab:
        return _err("VALIDATION_ERROR", "At least one filter must be provided")

    msgs = world_doc.get("messages", [])
    if not isinstance(msgs, list):
        msgs = []

    # Known labels are derived from data. If there are no messages / no labels in store,
    # do NOT reject label values (cannot determine validity); simply return empty results.
    known_labels = set()
    for m in msgs:
        if isinstance(m, dict):
            lids = m.get("label_ids")
            if isinstance(lids, list):
                for lid in lids:
                    if isinstance(lid, str) and lid.strip():
                        known_labels.add(lid.strip())
    if lab and known_labels and lab not in known_labels:
        return _err("VALIDATION_ERROR", "Unknown/invalid label value", label=lab)

    fc_l = fc.lower()
    sc_l = sc.lower()

    out = []
    for m in msgs:
        if not isinstance(m, dict):
            continue

        if fc:
            frm = m.get("from_")
            if not isinstance(frm, str) or fc_l not in frm.lower():
                continue

        if sc:
            subj = m.get("subject")
            if not isinstance(subj, str) or sc_l not in subj.lower():
                continue

        if lab:
            lids = m.get("label_ids")
            if not isinstance(lids, list) or lab not in [x for x in lids if isinstance(x, str)]:
                continue

        out.append(m)

    # This service has no request-log collection in the provided schema; return normal envelope.
    return {
        "results": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": datetime.datetime.utcnow().isoformat() + "Z",
    }

