def gmail_send_email(to, subject, body, cc=None, **_extra):
    import json, os, datetime, time, random, string, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")
    if not isinstance(world, dict):
        world = {"account": "", "messages": [], "bot_user_id": "U_BOT", "channels": [], "contacts": [], "deals": []}

    def _is_email(s):
        return isinstance(s, str) and re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s.strip()) is not None

    # Validate required fields
    if not isinstance(to, list):
        resp = _err("VALIDATION_ERROR", "to must be an array of email addresses", field="to")
    elif len(to) == 0:
        resp = _err("VALIDATION_ERROR", "to must not be empty", field="to")
    elif not isinstance(subject, str) or not subject.strip():
        resp = _err("VALIDATION_ERROR", "subject is required and must be a non-empty string", field="subject")
    elif not isinstance(body, str) or body == "":
        resp = _err("VALIDATION_ERROR", "body is required and must be a string", field="body")
    elif cc is not None and not isinstance(cc, list):
        resp = _err("VALIDATION_ERROR", "cc must be an array of email addresses", field="cc")
    else:
        bad_to = [x for x in to if not _is_email(x)]
        if bad_to:
            resp = _err("VALIDATION_ERROR", "Invalid recipient email(s) in to", field="to", invalid=bad_to)
        else:
            cc_list = cc or []
            bad_cc = [x for x in cc_list if not _is_email(x)]
            if bad_cc:
                resp = _err("VALIDATION_ERROR", "Invalid email(s) in cc", field="cc", invalid=bad_cc)
            else:
                resp = None

    if resp is None:
        msgs = world.get("messages", [])
        if not isinstance(msgs, list):
            msgs = []

        # Generate unique hex-ish message id
        existing_ids = {m.get("id") for m in msgs if isinstance(m, dict)}
        mid = None
        for _ in range(50):
            cand = "".join(random.choices("0123456789abcdef", k=16))
            if cand not in existing_ids:
                mid = cand
                break
        if mid is None:
            resp = _err("CONFLICT", "Failed to allocate message id")
        else:
            now_ms = int(time.time() * 1000)
            from_addr = world.get("account") or "user@gmail.com"
            msg = {
                "id": mid,
                "from_": from_addr,
                "to": list(to),
                "cc": list(cc or []),
                "bcc": [],
                "subject": subject,
                "body_plain": body,
                "body_html": None,
                "label_ids": ["SENT"],
                "is_read": True,
                "is_starred": False,
                "date": now_ms,
                "internal_date": now_ms,
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "channel_id": "C_GEN",
                "user_id": world.get("bot_user_id") or "U_BOT",
                "text": "",
                "thread_ts": None,
                "reply_count": 0,
                "is_bot": True,
                "reactions": []
            }
            msgs.append(msg)
            world["messages"] = msgs
            try:
                _save("world.json", world)
            except Exception:
                resp = _err("CONFLICT", "Failed to persist sent message")
            else:
                resp = {"message": msg}

    # Audit
    world2 = _load("world.json")
    if not isinstance(world2, dict):
        world2 = world
    try:
        calls = world2.get("_audit_calls")
        if not isinstance(calls, list):
            calls = []
        calls.append({
            "endpoint": "gmail_send_email",
            "status": "error" if isinstance(resp, dict) and "error" in resp else "ok",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000)
