def slack_list_channels(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0169000" if __import__("os").path.isdir("./environment_mix/0169000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")
    if not isinstance(world, dict):
        world = {"account": "", "messages": [], "bot_user_id": "U_BOT", "channels": [], "contacts": [], "deals": []}

    # Validate limit
    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, int):
            resp = _err("VALIDATION_ERROR", "limit must be an integer")
            lim = None
        elif limit < 1 or limit > 200:
            resp = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
            lim = None
        else:
            resp = None
            lim = limit

    # Validate/parse cursor (opaque base64 of integer offset)
    offset = 0
    if "resp" not in locals() or resp is None:
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor.strip():
                resp = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            else:
                try:
                    raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                    s = raw.decode("utf-8")
                    if not s.startswith("offset:"):
                        resp = _err("VALIDATION_ERROR", "Invalid cursor")
                    else:
                        off = int(s.split("offset:", 1)[1])
                        if off < 0:
                            resp = _err("VALIDATION_ERROR", "Invalid cursor")
                        else:
                            offset = off
                            resp = None
                except Exception:
                    resp = _err("VALIDATION_ERROR", "Invalid cursor")

    channels = world.get("channels", [])
    if not isinstance(channels, list):
        channels = []

    if "resp" not in locals() or resp is None:
        if offset > len(channels):
            resp = _err("VALIDATION_ERROR", "Cursor is no longer usable for pagination")
        else:
            page = channels[offset:offset + lim]
            next_offset = offset + len(page)
            has_more = next_offset < len(channels)
            next_cursor = None
            if has_more:
                next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")
            resp = {
                "channels": page,
                "total": len(channels),
                "has_more": has_more,
                "next_cursor": next_cursor
            }

    # Audit
    try:
        calls = world.get("_audit_calls")
        if not isinstance(calls, list):
            calls = []
        calls.append({
            "endpoint": "slack_list_channels",
            "status": "error" if isinstance(resp, dict) and "error" in resp else "ok",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        world["_audit_calls"] = calls
        world["_audit_counters"] = world.get("_audit_counters", {})
        if not isinstance(world["_audit_counters"], dict):
            world["_audit_counters"] = {}
        world["_audit_counters"]["slack_list_channels"] = int(world["_audit_counters"].get("slack_list_channels", 0)) + 1
        _save("world.json", world)
    except Exception:
        return _err("CONFLICT", "Failed to persist audit log")

    return resp

